#include <bits/stdc++.h>using namespace std;// n -> squad soldiers// find indexed of min and max// ((n-1) - index of min) + (index of max) => total swaps// if index of max > index of min => total swaps --int main() {    int n;    cin >> n;    vector<int> a(n);    for(int i=0; i<n; i++) {        cin >> a[i];    }    int minimum = 0;    int maximum = 0;    for(int i=1; i<n; i++) {        if(a[i] > a[maximum]){            maximum = i;        }        if(a[i]<=a[minimum]){            minimum = i;        }    }    int total = ((n-1) - minimum) + (maximum);    if(maximum > minimum){        total--;    }    cout << total;     }